window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["bmw-m"]={html:"<div class=\"own-bmw-m\">\n  <header class=\"nav\">\n    <a class=\"nav-logo\" href=\"#top\" aria-label=\"Northwind M home\">\n      <span class=\"roundel\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 40\"><circle cx=\"20\" cy=\"20\" r=\"19\" fill=\"#000\" stroke=\"#fff\" stroke-width=\"1.4\"/><path d=\"M20 1a19 19 0 0 1 0 38z\" fill=\"#fff\"/><path d=\"M20 6.5a13.5 13.5 0 0 1 0 27z\" fill=\"#1c69d4\"/><path d=\"M20 12a8 8 0 0 1 0 16z\" fill=\"#fff\"/></svg></span>\n      <span class=\"nav-word\">NORTHWIND<sup>M</sup></span>\n    </a>\n    <nav class=\"nav-links\" aria-label=\"Primary\">\n      <a href=\"#models\">Models</a>\n      <a href=\"#topics\">Topics</a>\n      <a href=\"#magazine\">Magazine</a>\n      <a href=\"#config\">Configurator</a>\n      <a href=\"#fastlane\">Fastlane</a>\n    </nav>\n    <div class=\"nav-tools\">\n      <a href=\"#\" class=\"nav-icon nav-icon-search\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4.3-4.3\"/></svg></a>\n      <a href=\"#\" class=\"nav-icon\" aria-label=\"Account\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7\"/></svg></a>\n      <span class=\"nav-lang\">EN</span>\n      <button class=\"nav-burger\" type=\"button\" aria-label=\"Menu\" aria-expanded=\"false\"><span></span><span></span></button>\n    </div>\n  </header>\n\n  <section class=\"hero\" id=\"top\" aria-labelledby=\"heroH\">\n    <div class=\"hero-photo\" aria-hidden=\"true\">\n      <svg class=\"hero-car\" viewBox=\"0 0 900 340\" preserveAspectRatio=\"xMidYMax slice\">\n        <defs>\n          <linearGradient id=\"bcar\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n            <stop offset=\"0\" stop-color=\"#3a3a3a\"/><stop offset=\".55\" stop-color=\"#161616\"/><stop offset=\"1\" stop-color=\"#050505\"/>\n          </linearGradient>\n          <radialGradient id=\"blight\" cx=\".5\" cy=\"0\" r=\"1\"><stop offset=\"0\" stop-color=\"#fff\" stop-opacity=\".5\"/><stop offset=\"1\" stop-color=\"#fff\" stop-opacity=\"0\"/></radialGradient>\n        </defs>\n        <ellipse cx=\"450\" cy=\"60\" rx=\"380\" ry=\"120\" fill=\"url(#blight)\"/>\n        <path d=\"M150 250c20-46 60-92 120-110 90-28 300-30 380 6 46 20 70 54 84 104z\" fill=\"url(#bcar)\"/>\n        <path d=\"M300 168c40-26 120-34 190-24 46 6 74 22 96 46-96-6-206-6-286-22z\" fill=\"#0c0c0c\"/>\n        <path d=\"M120 250h700\" stroke=\"#4a4a4a\" stroke-width=\"2\"/>\n        <circle cx=\"286\" cy=\"252\" r=\"40\" fill=\"#080808\" stroke=\"#2c2c2c\" stroke-width=\"3\"/>\n        <circle cx=\"286\" cy=\"252\" r=\"17\" fill=\"#1c69d4\"/>\n        <circle cx=\"640\" cy=\"252\" r=\"40\" fill=\"#080808\" stroke=\"#2c2c2c\" stroke-width=\"3\"/>\n        <circle cx=\"640\" cy=\"252\" r=\"17\" fill=\"#1c69d4\"/>\n      </svg>\n      <span class=\"hero-streak\"></span>\n      <span class=\"hero-streak b\"></span>\n      <span class=\"hero-grain\"></span>\n    </div>\n    <div class=\"hero-copy\">\n      <p class=\"hero-kicker\">Northwind M · Operations analytics</p>\n      <h1 id=\"heroH\">THE ULTIMATE<br>OPERATIONS MACHINE.</h1>\n      <p class=\"hero-sub\">Every dashboard, every region, every throughput signal — engineered into one command surface and driven at speed.</p>\n      <div class=\"hero-cta\">\n        <a class=\"btn btn-outline\" href=\"#models\">Explore the platform</a>\n        <a class=\"link-arrow\" href=\"#magazine\">Read the field notes <span aria-hidden=\"true\">&rarr;</span></a>\n      </div>\n    </div>\n    <ul class=\"hero-stats\" aria-label=\"Platform at a glance\">\n      <li><b>2.8M</b><span>events / minute</span></li>\n      <li><b>41</b><span>regions live</span></li>\n      <li><b>99.99%</b><span>uptime</span></li>\n    </ul>\n  </section>\n\n  <div class=\"mstripe\" aria-hidden=\"true\"></div>\n\n  <section class=\"topics\" id=\"topics\" aria-labelledby=\"topicsH\">\n    <div class=\"band-inner\">\n      <div class=\"band-head\">\n        <p class=\"eyebrow\">Vehicle telemetry, instrumented</p>\n        <h2 id=\"topicsH\" class=\"display-lg\">EVERY SIGNAL<br>AT SPEED.</h2>\n      </div>\n      <div class=\"spec-grid\">\n        <div class=\"spec\"><b>1.9s</b><span>Query latency p50</span></div>\n        <div class=\"spec\"><b>1.2TB</b><span>Daily ingest</span></div>\n        <div class=\"spec\"><b>0.6s</b><span>Live refresh</span></div>\n        <div class=\"spec\"><b>12</b><span>Data planes</span></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"magazine\" id=\"magazine\" aria-labelledby=\"magH\">\n    <div class=\"band-inner\">\n      <div class=\"band-head\">\n        <p class=\"eyebrow\">From the Northwind M magazine</p>\n        <h2 id=\"magH\" class=\"display-lg\">FIELD NOTES.</h2>\n      </div>\n      <div class=\"cards3\">\n        <article class=\"mcard\">\n          <div class=\"mcard-img ph-1\" aria-hidden=\"true\"></div>\n          <p class=\"tag\">Engineering</p>\n          <h3>Telemetry at the edge of the track</h3>\n          <p class=\"mcard-body\">Streaming ingestion that keeps pace with forty-one regional pipelines without shedding a single event.</p>\n          <a class=\"link-arrow\" href=\"#\">Read the story <span aria-hidden=\"true\">&rarr;</span></a>\n        </article>\n        <article class=\"mcard\">\n          <div class=\"mcard-img ph-2\" aria-hidden=\"true\"></div>\n          <p class=\"tag\">Operations</p>\n          <h3>One cockpit for every region</h3>\n          <p class=\"mcard-body\">Unified dashboards that let operations leads compare throughput and cost across the whole grid in a glance.</p>\n          <a class=\"link-arrow\" href=\"#\">Read the story <span aria-hidden=\"true\">&rarr;</span></a>\n        </article>\n        <article class=\"mcard\">\n          <div class=\"mcard-img ph-3\" aria-hidden=\"true\"></div>\n          <p class=\"tag\">Motorsport</p>\n          <h3>Alerts that arrive before the redline</h3>\n          <p class=\"mcard-body\">Predictive thresholds tuned on racing telemetry patterns, now watching your production fleet.</p>\n          <a class=\"link-arrow\" href=\"#\">Read the story <span aria-hidden=\"true\">&rarr;</span></a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <div class=\"mstripe\" aria-hidden=\"true\"></div>\n\n  <section class=\"models\" id=\"models\" aria-labelledby=\"modelsH\">\n    <div class=\"band-inner\">\n      <div class=\"band-head\">\n        <p class=\"eyebrow\">The lineup</p>\n        <h2 id=\"modelsH\" class=\"display-lg\">MORE NORTHWIND M.</h2>\n      </div>\n      <div class=\"cards3 models-grid\">\n        <article class=\"model\">\n          <div class=\"model-img ph-4\" aria-hidden=\"true\"></div>\n          <h3 class=\"display-md\">Ops Core</h3>\n          <p class=\"model-spec\">Single-region dashboards · 1M events/min</p>\n          <a class=\"link-arrow\" href=\"#\">Explore this model <span aria-hidden=\"true\">&rarr;</span></a>\n        </article>\n        <article class=\"model\">\n          <div class=\"model-img ph-5\" aria-hidden=\"true\"></div>\n          <h3 class=\"display-md\">Ops Grid</h3>\n          <p class=\"model-spec\">Multi-region federation · 12 data planes</p>\n          <a class=\"link-arrow\" href=\"#\">Explore this model <span aria-hidden=\"true\">&rarr;</span></a>\n        </article>\n        <article class=\"model\">\n          <div class=\"model-img ph-6\" aria-hidden=\"true\"></div>\n          <h3 class=\"display-md\">Ops Fastlane</h3>\n          <p class=\"model-spec\">Realtime streaming · sub-second refresh</p>\n          <a class=\"link-arrow\" href=\"#\">Explore this model <span aria-hidden=\"true\">&rarr;</span></a>\n        </article>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"config\" id=\"config\" aria-labelledby=\"configH\">\n    <div class=\"band-inner config-inner\">\n      <div class=\"config-copy\">\n        <p class=\"eyebrow\">Configurator</p>\n        <h2 id=\"configH\" class=\"display-lg\">BUILD YOUR<br>OPERATIONS SURFACE.</h2>\n        <p class=\"hero-sub\">Pick regions, throughput tiers and retention, then watch the price resolve live.</p>\n        <div class=\"config-tabs\" role=\"tablist\" aria-label=\"Plan\">\n          <button type=\"button\" role=\"tab\" class=\"tab\" aria-selected=\"true\" data-plan=\"core\">Core</button>\n          <button type=\"button\" role=\"tab\" class=\"tab\" aria-selected=\"false\" data-plan=\"grid\">Grid</button>\n          <button type=\"button\" role=\"tab\" class=\"tab\" aria-selected=\"false\" data-plan=\"fastlane\">Fastlane</button>\n        </div>\n        <div class=\"config-price\">\n          <span class=\"price-num\" id=\"cfgPrice\">$1,200</span>\n          <span class=\"price-unit\">/ month</span>\n        </div>\n        <a class=\"btn btn-outline\" href=\"#fastlane\">Request a build slot</a>\n      </div>\n      <div class=\"config-panel\" aria-live=\"polite\">\n        <div class=\"config-row\"><span>Regions</span><b id=\"cfgRegions\">4</b></div>\n        <div class=\"config-row\"><span>Throughput</span><b id=\"cfgThroughput\">800k/min</b></div>\n        <div class=\"config-row\"><span>Retention</span><b id=\"cfgRetention\">13 months</b></div>\n        <div class=\"config-row\"><span>Support</span><b id=\"cfgSupport\">Business hours</b></div>\n        <div class=\"config-meter\"><span id=\"cfgMeter\"></span></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"cta\" id=\"fastlane\" aria-labelledby=\"ctaH\">\n    <div class=\"cta-photo\" aria-hidden=\"true\"><span class=\"hero-streak c\"></span><span class=\"hero-grain\"></span></div>\n    <div class=\"cta-inner\">\n      <h2 id=\"ctaH\" class=\"display-md\">DRIVE AN M.</h2>\n      <p class=\"hero-sub\">Put Northwind M behind your next operations review.</p>\n      <a class=\"btn btn-outline\" href=\"#\">Book a walkthrough</a>\n    </div>\n  </section>\n\n  <footer class=\"foot\">\n    <div class=\"band-inner\">\n      <div class=\"foot-cols\">\n        <div class=\"foot-col\">\n          <p class=\"foot-h\">Northwind M Models</p>\n          <a href=\"#\">Ops Core</a><a href=\"#\">Ops Grid</a><a href=\"#\">Ops Fastlane</a><a href=\"#\">Compare</a>\n        </div>\n        <div class=\"foot-col\">\n          <p class=\"foot-h\">Northwind M Lifestyle</p>\n          <a href=\"#\">Field notes</a><a href=\"#\">Benchmarks</a><a href=\"#\">Community</a>\n        </div>\n        <div class=\"foot-col\">\n          <p class=\"foot-h\">Owners</p>\n          <a href=\"#\">Support</a><a href=\"#\">Status</a><a href=\"#\">Docs</a><a href=\"#\">Security</a>\n        </div>\n        <div class=\"foot-col\">\n          <p class=\"foot-h\">Company</p>\n          <a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a><a href=\"#\">Legal</a>\n        </div>\n      </div>\n      <div class=\"foot-bottom\">\n        <p>Northwind is a fictional product. Sample data — showcase only.</p>\n        <span class=\"foot-lang\">EN · Metric</span>\n      </div>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND M — own layout in the BMW M design language ═══════════════\n   Scoped under .own-bmw-m. Tokens from design-md/bmw-m/DESIGN.md. Near-pure\n   black canvas, white UPPERCASE display (700) vs light body (300), M tricolor\n   stripe as the only decorative element, 0px radius everywhere, photography\n   (SVG/CSS) as the depth. Container queries drive Tablet/Phone reflow. */\n\n.own-bmw-m {\n  --canvas: #000000;\n  --surface-soft: #0d0d0d;\n  --surface-card: #1a1a1a;\n  --surface-elevated: #262626;\n  --carbon: #2b2b2b;\n  --hairline: #3c3c3c;\n  --hairline-strong: #262626;\n  --ink: #ffffff;\n  --body: #bbbbbb;\n  --body-strong: #e6e6e6;\n  --muted: #7e7e7e;\n  --m-blue-light: #0066b1;\n  --m-blue-dark: #1c69d4;\n  --m-red: #e22718;\n  --warning: #f4b400;\n\n  --display: \"BMWTypeNextLatin\", \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif;\n  --body-font: \"BMWTypeNextLatin Light\", \"BMWTypeNextLatin\", \"Inter\", sans-serif;\n\n  --gut: clamp(20px, 4.6cqi, 60px);\n  --section: clamp(56px, 8cqi, 96px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--body-font);\n  font-size: 16px;\n  font-weight: 300;\n  line-height: 1.5;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n}\n.own-bmw-m *,\n.own-bmw-m *::before,\n.own-bmw-m *::after { box-sizing: border-box; }\n.own-bmw-m :focus-visible { outline: 2px solid var(--ink); outline-offset: 3px; }\n.own-bmw-m a { color: inherit; text-decoration: none; }\n\n.own-bmw-m .band-inner { max-width: 1440px; margin: 0 auto; padding: 0 var(--gut); }\n\n/* ── type ─────────────────────────────────────────────────────────────── */\n.own-bmw-m .display-lg {\n  font-family: var(--display);\n  font-weight: 700;\n  text-transform: uppercase;\n  font-size: clamp(34px, 5.4cqi, 56px);\n  line-height: 1.05;\n  letter-spacing: 0;\n}\n.own-bmw-m .display-md {\n  font-family: var(--display);\n  font-weight: 700;\n  text-transform: uppercase;\n  font-size: clamp(26px, 3.4cqi, 40px);\n  line-height: 1.1;\n}\n.own-bmw-m .eyebrow {\n  font-family: var(--display);\n  font-weight: 700;\n  font-size: 12px;\n  letter-spacing: 1.5px;\n  text-transform: uppercase;\n  color: var(--body);\n  margin-bottom: 16px;\n}\n.own-bmw-m .tag {\n  font-family: var(--display);\n  font-weight: 700;\n  font-size: 12px;\n  letter-spacing: 1.5px;\n  text-transform: uppercase;\n  color: var(--muted);\n  margin: 0 0 10px;\n}\n.own-bmw-m .hero-sub { color: var(--body); font-weight: 300; font-size: 16px; max-width: 52ch; }\n\n/* ── buttons / links ─────────────────────────────────────────────────── */\n.own-bmw-m .btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 48px; padding: 0 32px; border-radius: 0;\n  font-family: var(--display); font-weight: 700; font-size: 14px;\n  letter-spacing: 1.5px; text-transform: uppercase;\n  transition: background-color .25s ease, color .25s ease, border-color .25s ease;\n}\n.own-bmw-m .btn-outline { background: transparent; color: var(--ink); border: 1px solid var(--ink); }\n.own-bmw-m .btn-outline:hover { background: var(--ink); color: var(--canvas); }\n.own-bmw-m .link-arrow {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-family: var(--display); font-weight: 700; font-size: 13px;\n  letter-spacing: 1.5px; text-transform: uppercase; color: var(--ink);\n}\n.own-bmw-m .link-arrow span { transition: transform .25s ease; }\n.own-bmw-m .link-arrow:hover span { transform: translateX(5px); }\n\n/* ── nav ──────────────────────────────────────────────────────────────── */\n.own-bmw-m .nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 28px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(0, 0, 0, .92);\n  border-bottom: 1px solid var(--hairline-strong);\n  backdrop-filter: blur(8px);\n}\n.own-bmw-m .nav-logo { display: inline-flex; align-items: center; gap: 12px; }\n.own-bmw-m .roundel { width: 34px; height: 34px; display: block; flex: none; }\n.own-bmw-m .roundel svg { width: 100%; height: 100%; display: block; }\n.own-bmw-m .nav-word { font-family: var(--display); font-weight: 700; font-size: 18px; letter-spacing: 1.5px; white-space: nowrap; }\n.own-bmw-m .nav-word sup { font-size: 9px; letter-spacing: 1px; margin-left: 2px; color: var(--m-blue-dark); }\n.own-bmw-m .nav-links { display: flex; align-items: center; gap: 26px; margin-left: 14px; }\n.own-bmw-m .nav-links a {\n  font-family: var(--display); font-weight: 400; font-size: 14px; letter-spacing: .5px;\n  color: var(--body); padding: 6px 0; border-bottom: 2px solid transparent; transition: color .2s, border-color .2s;\n}\n.own-bmw-m .nav-links a:hover { color: var(--ink); border-color: var(--m-blue-dark); }\n.own-bmw-m .nav-tools { margin-left: auto; display: flex; align-items: center; gap: 6px; }\n.own-bmw-m .nav-icon { display: grid; place-items: center; width: 48px; height: 48px; color: var(--ink); }\n.own-bmw-m .nav-icon svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.own-bmw-m .nav-icon:hover { background: var(--surface-card); }\n.own-bmw-m .nav-lang { font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: 1.5px; padding: 0 12px; color: var(--body); }\n.own-bmw-m .nav-burger { display: none; width: 48px; height: 48px; flex-direction: column; align-items: center; justify-content: center; gap: 6px; background: none; border: 0; cursor: pointer; }\n.own-bmw-m .nav-burger span { display: block; width: 22px; height: 2px; background: var(--ink); transition: transform .25s, opacity .25s; }\n.own-bmw-m .nav-burger[aria-expanded=\"true\"] span:first-child { transform: translateY(4px) rotate(45deg); }\n.own-bmw-m .nav-burger[aria-expanded=\"true\"] span:last-child { transform: translateY(-4px) rotate(-45deg); }\n\n/* ── hero ─────────────────────────────────────────────────────────────── */\n.own-bmw-m .hero {\n  position: relative; isolation: isolate; overflow: hidden;\n  min-height: min(760px, 88cqi);\n  display: flex; flex-direction: column; justify-content: flex-end;\n  padding: clamp(72px, 14cqi, 120px) var(--gut) clamp(40px, 6cqi, 64px);\n}\n.own-bmw-m .hero-photo { position: absolute; inset: 0; z-index: -2; background: radial-gradient(120% 80% at 50% 12%, #1c1c1c 0%, #060606 62%, #000 100%); }\n.own-bmw-m .hero-car { position: absolute; left: 50%; bottom: 0; width: min(900px, 92%); transform: translateX(-50%); opacity: .96; }\n.own-bmw-m .hero-streak { position: absolute; left: -10%; right: -10%; height: 2px; top: 42%; background: linear-gradient(90deg, transparent, rgba(255,255,255,.55), transparent); opacity: .5; }\n.own-bmw-m .hero-streak.b { top: 58%; height: 1px; opacity: .35; }\n.own-bmw-m .hero-streak.c { position: absolute; top: 50%; }\n.own-bmw-m .hero-grain { position: absolute; inset: 0; background: linear-gradient(0deg, rgba(0,0,0,.9) 0%, rgba(0,0,0,.35) 34%, transparent 62%); }\n.own-bmw-m .hero-copy { position: relative; z-index: 1; }\n.own-bmw-m .hero-kicker {\n  font-family: var(--display); font-weight: 700; font-size: 13px; letter-spacing: 1.5px;\n  text-transform: uppercase; color: var(--body); margin: 0 0 14px;\n}\n.own-bmw-m .hero h1 {\n  font-family: var(--display); font-weight: 700; text-transform: uppercase;\n  font-size: clamp(46px, 8.4cqi, 80px); line-height: 1; letter-spacing: 0; margin: 0;\n}\n.own-bmw-m .hero-sub { margin: 22px 0 30px; color: var(--body-strong); }\n.own-bmw-m .hero-cta { display: flex; align-items: center; gap: 26px; flex-wrap: wrap; }\n.own-bmw-m .hero-stats {\n  position: absolute; top: 50%; right: var(--gut); transform: translateY(-50%);\n  z-index: 1; list-style: none; margin: 0; padding: 0; display: grid; gap: 26px; text-align: right;\n}\n.own-bmw-m .hero-stats b { display: block; font-family: var(--display); font-weight: 700; font-size: clamp(28px, 3.2cqi, 44px); line-height: 1; }\n.own-bmw-m .hero-stats span { font-family: var(--display); font-weight: 700; font-size: 11px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); }\n\n/* ── M tricolor stripe ───────────────────────────────────────────────── */\n.own-bmw-m .mstripe {\n  height: 4px; margin: 0; background: linear-gradient(90deg, var(--m-blue-light) 0 33.33%, var(--m-blue-dark) 33.33% 66.66%, var(--m-red) 66.66% 100%);\n}\n\n/* ── topics / spec ───────────────────────────────────────────────────── */\n.own-bmw-m .topics { padding: var(--section) 0; background: var(--canvas); }\n.own-bmw-m .band-head { max-width: 720px; margin-bottom: 44px; }\n.own-bmw-m .spec-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: var(--hairline); border: 1px solid var(--hairline); }\n.own-bmw-m .spec { background: var(--surface-soft); padding: 32px 24px; }\n.own-bmw-m .spec b { display: block; font-family: var(--display); font-weight: 700; font-size: clamp(28px, 3cqi, 40px); line-height: 1; margin-bottom: 12px; }\n.own-bmw-m .spec span { font-family: var(--display); font-weight: 700; font-size: 11px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); }\n\n/* ── magazine cards ──────────────────────────────────────────────────── */\n.own-bmw-m .magazine { padding: var(--section) 0; background: var(--canvas); }\n.own-bmw-m .cards3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-bmw-m .mcard { background: var(--surface-card); padding: 24px; display: flex; flex-direction: column; }\n.own-bmw-m .mcard-img { height: 0; padding-bottom: 56.25%; margin: -24px -24px 20px; background-size: cover; position: relative; overflow: hidden; }\n.own-bmw-m .mcard-img::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(120deg, rgba(255,255,255,.06), transparent 50%), repeating-linear-gradient(115deg, rgba(0,0,0,.35) 0 3px, transparent 3px 9px); }\n.own-bmw-m .ph-1 { background-image: radial-gradient(120% 90% at 70% 20%, #2b2b2b, #0a0a0a), linear-gradient(90deg, #161616, #2b2b2b); }\n.own-bmw-m .ph-2 { background-image: radial-gradient(90% 80% at 30% 70%, #16365a, #050505); }\n.own-bmw-m .ph-3 { background-image: radial-gradient(110% 90% at 50% 30%, #4a1410, #070707); }\n.own-bmw-m .ph-4 { background-image: radial-gradient(100% 90% at 60% 25%, #242424, #060606); }\n.own-bmw-m .ph-5 { background-image: radial-gradient(100% 90% at 40% 30%, #123152, #060606); }\n.own-bmw-m .ph-6 { background-image: radial-gradient(100% 90% at 55% 30%, #3d100c, #060606); }\n.own-bmw-m .mcard h3 { font-family: var(--display); font-weight: 700; font-size: 20px; line-height: 1.4; margin: 0 0 10px; }\n.own-bmw-m .mcard-body { color: var(--body); font-size: 15px; margin: 0 0 18px; }\n.own-bmw-m .mcard .link-arrow { margin-top: auto; }\n\n/* ── models ──────────────────────────────────────────────────────────── */\n.own-bmw-m .models { padding: var(--section) 0; background: var(--canvas); }\n.own-bmw-m .model { display: flex; flex-direction: column; }\n.own-bmw-m .model-img { height: 0; padding-bottom: 62%; background-size: cover; margin-bottom: 22px; }\n.own-bmw-m .model h3 { margin: 0 0 8px; }\n.own-bmw-m .model-spec { font-weight: 300; font-size: 14px; color: var(--body); margin: 0 0 16px; }\n.own-bmw-m .model .link-arrow { margin-top: auto; }\n\n/* ── configurator ────────────────────────────────────────────────────── */\n.own-bmw-m .config { padding: var(--section) 0; background: var(--surface-soft); }\n.own-bmw-m .config-inner { display: grid; grid-template-columns: 1.1fr .9fr; gap: clamp(24px, 4cqi, 64px); align-items: center; }\n.own-bmw-m .config-tabs { display: flex; gap: 0; margin: 28px 0 24px; border-bottom: 1px solid var(--hairline); }\n.own-bmw-m .config .tab {\n  background: none; border: 0; cursor: pointer; padding: 12px 22px 12px 0; margin-right: 22px;\n  font-family: var(--display); font-weight: 700; font-size: 13px; letter-spacing: 1.5px; text-transform: uppercase;\n  color: var(--body); border-bottom: 2px solid transparent; transition: color .2s, border-color .2s;\n}\n.own-bmw-m .config .tab[aria-selected=\"true\"] { color: var(--ink); border-color: var(--ink); }\n.own-bmw-m .config-price { display: flex; align-items: baseline; gap: 10px; margin-bottom: 26px; }\n.own-bmw-m .price-num { font-family: var(--display); font-weight: 700; font-size: clamp(40px, 5cqi, 64px); line-height: 1; font-variant-numeric: tabular-nums; }\n.own-bmw-m .price-unit { font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); }\n.own-bmw-m .config-panel { background: var(--surface-card); padding: 32px; }\n.own-bmw-m .config-row { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; padding: 18px 0; border-bottom: 1px solid var(--hairline); }\n.own-bmw-m .config-row span { font-family: var(--display); font-weight: 700; font-size: 11px; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); }\n.own-bmw-m .config-row b { font-family: var(--display); font-weight: 700; font-size: 18px; font-variant-numeric: tabular-nums; }\n.own-bmw-m .config-meter { margin-top: 22px; height: 4px; background: var(--hairline); overflow: hidden; }\n.own-bmw-m .config-meter span { display: block; height: 100%; width: 30%; background: linear-gradient(90deg, var(--m-blue-light), var(--m-blue-dark) 60%, var(--m-red)); transition: width .5s cubic-bezier(.16,1,.3,1); }\n\n/* ── CTA band ────────────────────────────────────────────────────────── */\n.own-bmw-m .cta { position: relative; isolation: isolate; overflow: hidden; padding: clamp(64px, 8cqi, 80px) var(--gut); text-align: center; }\n.own-bmw-m .cta-photo { position: absolute; inset: 0; z-index: -2; background: radial-gradient(120% 120% at 50% 120%, #241010 0%, #0a0a0a 55%, #000 100%); }\n.own-bmw-m .cta-inner { max-width: 640px; margin: 0 auto; }\n.own-bmw-m .cta .hero-sub { margin: 18px auto 28px; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-bmw-m .foot { background: var(--canvas); padding: clamp(48px, 6cqi, 64px) 0 32px; border-top: 1px solid var(--hairline-strong); }\n.own-bmw-m .foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-bmw-m .foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-bmw-m .foot-h { font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: 1.5px; text-transform: uppercase; margin: 0 0 6px; }\n.own-bmw-m .foot-col a { color: var(--muted); font-size: 14px; font-weight: 300; }\n.own-bmw-m .foot-col a:hover { color: var(--ink); }\n.own-bmw-m .foot-bottom { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 40px; padding-top: 20px; border-top: 1px solid var(--hairline); }\n.own-bmw-m .foot-bottom p { font-size: 12px; letter-spacing: .5px; color: var(--muted); margin: 0; }\n.own-bmw-m .foot-lang { font-family: var(--display); font-weight: 700; font-size: 12px; letter-spacing: 1.5px; color: var(--muted); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-bmw-m .hero-stats { display: none; }\n  .own-bmw-m .spec-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-bmw-m .cards3, .own-bmw-m .models-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-bmw-m .config-inner { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-bmw-m .nav { gap: 12px; }\n  .own-bmw-m .nav-links { display: none; }\n  .own-bmw-m .nav-burger { display: flex; }\n  .own-bmw-m .nav-lang, .own-bmw-m .nav-icon-search { display: none; }\n  .own-bmw-m .hero { min-height: 78cqi; }\n  .own-bmw-m .hero-stats { position: static; transform: none; display: grid; grid-template-columns: repeat(3, 1fr); text-align: left; gap: 12px; margin-top: 32px; }\n  .own-bmw-m .hero-stats span { font-size: 9.5px; }\n  .own-bmw-m .cards3, .own-bmw-m .models-grid, .own-bmw-m .spec-grid { grid-template-columns: 1fr; }\n  .own-bmw-m .foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-bmw-m .foot-cols { grid-template-columns: 1fr; }\n  .own-bmw-m .config-panel { padding: 22px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-bmw-m *, .own-bmw-m *::before, .own-bmw-m *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND M — own-layout behaviour for showcase.html ════════════════
   The configurator resolves a plan from the active tab; the burger toggles
   the phone menu. Query only inside root, remove listeners on cleanup. */
(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var PLANS = {
    core: { price: 1200, regions: '4', throughput: '800k/min', retention: '13 months', support: 'Business hours', meter: 30 },
    grid: { price: 3400, regions: '18', throughput: '2.4M/min', retention: '25 months', support: '24/7 follow-the-sun', meter: 62 },
    fastlane: { price: 6800, regions: '41', throughput: '6M/min', retention: '36 months', support: 'Dedicated crew', meter: 92 }
  };

  window.OWN_LAYOUTS['bmw-m'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(sel) { return root.querySelector(sel); }
      function $$(sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); }

      function render(plan) {
        var p = PLANS[plan] || PLANS.core;
        var price = $('#cfgPrice');
        if (price) price.textContent = '$' + p.price.toLocaleString('en-US');
        if ($('#cfgRegions')) $('#cfgRegions').textContent = p.regions;
        if ($('#cfgThroughput')) $('#cfgThroughput').textContent = p.throughput;
        if ($('#cfgRetention')) $('#cfgRetention').textContent = p.retention;
        if ($('#cfgSupport')) $('#cfgSupport').textContent = p.support;
        if ($('#cfgMeter')) $('#cfgMeter').style.width = p.meter + '%';
      }

      on($('.config-tabs'), 'click', function (e) {
        var b = e.target.closest('[data-plan]');
        if (!b) return;
        $$('.config .tab').forEach(function (t) { t.setAttribute('aria-selected', String(t === b)); });
        render(b.dataset.plan);
      });

      var burger = $('.nav-burger');
      var links = $('.nav-links');
      on(burger, 'click', function () {
        var open = burger.getAttribute('aria-expanded') === 'true';
        burger.setAttribute('aria-expanded', String(!open));
        if (links) {
          links.style.display = !open ? 'flex' : '';
          if (!open) {
            links.style.position = 'absolute';
            links.style.top = '100%';
            links.style.left = '0';
            links.style.right = '0';
            links.style.flexDirection = 'column';
            links.style.alignItems = 'flex-start';
            links.style.gap = '4px';
            links.style.padding = '16px var(--gut) 20px';
            links.style.background = 'rgba(0,0,0,.97)';
            links.style.borderBottom = '1px solid var(--hairline)';
          } else {
            links.removeAttribute('style');
          }
        }
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        if (links) links.removeAttribute('style');
        if (burger) burger.setAttribute('aria-expanded', 'false');
        void disposed;
      };
    }
  };
})();
